// @ts-check
// Build step 3 of DESIGN.md section 11 "Deploy": build dist/ and its service worker.
//
// buildDist({ root, out, hash }) produces:
//   out/v/<hash>/src/...      every src/**/*.js module (registries regenerated first)
//   out/index.html            (and teacher.html when it exists) with each src="src/..."
//                             and href="src/..." rewritten to "v/<hash>/src/..."
//   out/manifest.webmanifest  copied
//   out/icons/*.png           regenerated by gen-icons.js
//   out/api/{sync,pair,lib}.php
//   out/.htaccess             from api/.htaccess (that file is the WEB-ROOT config; see its header)
//   out/proto/                proto/index.html, style.css, js/** (no tests)
//   out/.keystone-dist        marker (checkOut): only a missing, empty or marked
//                             out is ever deleted; not precached, not uploaded
//   out/sw.js                 generated: cache-first, cache name "keystone:<scope path>:<hash>"
//                             (staging and production share an origin; each worker
//                             deletes only its own scope's older caches),
//                             precache list = every shipped file except api/ and .htaccess
// and then hard-fails unless:
//   - every module reachable by import from src/app/boot.js and teacher.html is precached;
//   - every precached file exists in out/;
//   - no shipped HTML, manifest or JS uses an absolute-path or absolute URL
//     (absoluteUrlViolations), because staging lives at /staging/.
//
// Every URL is relative. sw.js resolves its precache entries against its own
// location (the app root), so the same dist/ works at / and at /staging/.
//
// The service worker never calls skipWaiting() on its own: a new version
// waits until the page (boot.js createUpdater) posts {type: 'skip-waiting'}
// while no run is in progress. Install refuses a fetched index.html that does
// not reference v/<BUILD>/, so a half-uploaded deploy can never be cached as a
// consistent version.
//
// Run: node scripts/gen-sw.js --hash <git short hash> [--out dist] [--root .]

import { readFileSync, writeFileSync, mkdirSync, rmSync, existsSync, readdirSync, copyFileSync, statSync } from 'node:fs';
import { join, dirname, resolve, relative, sep, posix } from 'node:path';
import { fileURLToPath } from 'node:url';
import { genRegistry } from './gen-registry.js';
import { writeIcons } from './gen-icons.js';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const RE_HASH = /^[0-9a-f]{7,40}$/;

/** @param {string} p */
const posixRel = (p) => p.split(sep).join('/');

/** @param {string} dir @returns {string[]} absolute file paths, sorted */
function walk(dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true })
    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    .flatMap((e) => {
      const p = join(dir, e.name);
      if (e.isDirectory()) return walk(p);
      return e.isFile() ? [p] : [];
    });
}

/** @param {string} src */
function stripComments(src) {
  return src.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:\\'"`])\/\/.*$/gm, '$1');
}

/**
 * Static, re-export and literal dynamic import specifiers of a module.
 * @param {string} src
 * @returns {string[]}
 */
export function importSpecifiers(src) {
  const s = stripComments(src);
  const out = [];
  const patterns = [
    /\bimport\s+(?:[\w*{}\s,$]+?\s+from\s+)?['"]([^'"]+)['"]/g,
    /\bexport\s+(?:\*(?:\s+as\s+[\w$]+)?|\{[^}]*\})\s+from\s+['"]([^'"]+)['"]/g,
    /\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/g,
  ];
  for (const re of patterns) for (const m of s.matchAll(re)) out.push(m[1]);
  return out;
}

/** @param {string} html @returns {string[]} module script src values */
export function moduleScripts(html) {
  return [...html.matchAll(/<script\b[^>]*\btype\s*=\s*["']module["'][^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>/gi)]
    .map((m) => m[1]);
}

/**
 * Repo-relative paths of every module reachable from the entry modules.
 * Throws on an import that does not resolve to an existing file.
 * @param {string} root @param {string[]} entries repo-relative paths
 * @returns {string[]} sorted
 */
export function reachableModules(root, entries) {
  const seen = new Set();
  const stack = [...entries];
  while (stack.length) {
    const rel = /** @type {string} */ (stack.pop());
    if (seen.has(rel)) continue;
    const abs = join(root, rel);
    if (!existsSync(abs)) throw new Error(`reachableModules: ${rel} does not exist`);
    seen.add(rel);
    for (const spec of importSpecifiers(readFileSync(abs, 'utf8'))) {
      if (!spec.startsWith('./') && !spec.startsWith('../')) throw new Error(`reachableModules: ${rel} imports non-relative ${spec}`);
      stack.push(posix.normalize(posix.join(posix.dirname(rel), spec)));
    }
  }
  return [...seen].sort();
}

/**
 * Absolute-path / absolute URLs in shipped text files. Staging is served
 * from /staging/, so any of these would break it.
 * HTML: src/href/action/poster/srcset attributes and CSS url().
 * Manifest: start_url, scope, id, and every icon src.
 * JS: import specifiers, and the first string argument of fetch, register,
 * importScripts, new URL, new Request, new Worker. In sw.js, every precache entry.
 * strict JS (M3's own modules): every string literal.
 * @param {{ path: string; text: string; strict?: boolean }[]} files
 * @returns {string[]}
 */
export function absoluteUrlViolations(files) {
  const bad = (/** @type {string} */ u) => /^\s*(\/|[a-zA-Z][a-zA-Z0-9+.-]*:)/.test(u);
  const errs = [];
  for (const { path, text, strict } of files) {
    if (path.endsWith('.html') || path.endsWith('.css')) {
      for (const m of text.matchAll(/\b(src|href|action|poster|srcset)\s*=\s*(["'])(.*?)\2/gi)) {
        if (bad(m[3])) errs.push(`${path}: ${m[1]}="${m[3]}"`);
      }
      for (const m of text.matchAll(/url\(\s*(["']?)([^"')]*)\1\s*\)/gi)) {
        if (bad(m[2])) errs.push(`${path}: url(${m[2]})`);
      }
    } else if (path.endsWith('.webmanifest')) {
      /** @type {any} */
      let j;
      try { j = JSON.parse(text); } catch { errs.push(`${path}: not JSON`); continue; }
      for (const k of ['start_url', 'scope']) {
        if (typeof j[k] !== 'string') errs.push(`${path}: ${k} missing`);
        else if (bad(j[k])) errs.push(`${path}: ${k} "${j[k]}"`);
      }
      if (typeof j.id === 'string' && bad(j.id)) errs.push(`${path}: id "${j.id}"`);
      for (const ic of Array.isArray(j.icons) ? j.icons : []) {
        if (typeof ic?.src !== 'string' || bad(ic.src)) errs.push(`${path}: icon src ${JSON.stringify(ic?.src)}`);
      }
    } else if (path.endsWith('.js')) {
      const s = stripComments(text);
      for (const spec of importSpecifiers(text)) {
        if (!spec.startsWith('./') && !spec.startsWith('../')) errs.push(`${path}: import ${JSON.stringify(spec)}`);
      }
      const sink = /\b(fetch|register|importScripts|URL|Request|Worker)\s*\(\s*(['"`])(.*?)\2/g;
      for (const m of s.matchAll(sink)) if (bad(m[3])) errs.push(`${path}: ${m[1]}(${JSON.stringify(m[3])})`);
      const pre = /\bconst PRECACHE = (\[[\s\S]*?\]);/.exec(s);
      if (pre) for (const u of JSON.parse(pre[1])) if (bad(u)) errs.push(`${path}: precache ${JSON.stringify(u)}`);
      if (strict) {
        for (const m of s.matchAll(/(['"`])((?:\\.|(?!\1)[^\\\n])*)\1/g)) {
          if (/^(\/[A-Za-z0-9_.~-]|https?:|\/\/)/.test(m[2])) errs.push(`${path}: string ${JSON.stringify(m[2])}`);
        }
      }
    }
  }
  return errs;
}

/**
 * The service worker source.
 * @param {{ build: string; precache: string[] }} p
 */
export function swSource(p) {
  if (!RE_HASH.test(p.build)) throw new Error(`swSource: bad build hash ${p.build}`);
  return `// GENERATED by scripts/gen-sw.js -- do not edit, do not commit.
// Cache-first, keyed by the build hash. Waits for the page to ask before activating.
'use strict';
const BUILD = ${JSON.stringify(p.build)};
// Production (/) and staging (/staging/) share one origin and so one
// CacheStorage: the cache name carries the scope path, and this worker only
// ever deletes caches of its own scope.
const SCOPE_TAG = 'keystone:' + new URL(self.registration.scope).pathname;
const CACHE = SCOPE_TAG + ':' + BUILD;
const ownScope = (name) => name.lastIndexOf(':') > 0 && name.slice(0, name.lastIndexOf(':')) === SCOPE_TAG;
const PRECACHE = ${JSON.stringify(p.precache, null, 0)};
const PRECACHED = new Set(PRECACHE);

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    try {
      const got = await Promise.all(PRECACHE.map(async (url) => {
        const res = await fetch(new Request(url, { cache: 'reload' }));
        if (!res.ok) throw new Error('precache ' + url + ': HTTP ' + res.status);
        if (url === 'index.html') {
          const text = await res.clone().text();
          if (!text.includes('v/' + BUILD + '/')) throw new Error('index.html is not build ' + BUILD);
        }
        return [url, res];
      }));
      for (const [url, res] of got) await cache.put(url, res);
    } catch (err) {
      await caches.delete(CACHE);
      throw err;
    }
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (ownScope(name) && name !== CACHE) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const base = new URL(self.registration.scope).pathname;
  if (!url.pathname.startsWith(base)) return;
  let rel = decodeURIComponent(url.pathname.slice(base.length));
  if (req.mode === 'navigate' && (rel === '' || rel.endsWith('/'))) rel += 'index.html';
  if (!PRECACHED.has(rel)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(rel);
    return hit || fetch(req);
  })());
});
`;
}

/** Marker file that lets a later build delete `out`. Never shipped (deploy.sh excludes it). */
export const DIST_MARKER = '.keystone-dist';

/**
 * buildDist deletes `out` recursively, so it refuses unless `out` is missing,
 * an empty directory, or a directory carrying DIST_MARKER (a previous build).
 * Also refuses a filesystem root and any `out` that is or contains the source tree.
 * @param {string} out absolute @param {string} root
 */
export function checkOut(out, root) {
  const r = resolve(root);
  if (out === r || r.startsWith(out.endsWith(sep) ? out : out + sep)) throw new Error('buildDist: out would contain the source tree');
  if (dirname(out) === out) throw new Error(`buildDist: refusing to build into the filesystem root ${out}`);
  if (!existsSync(out)) return;
  if (!statSync(out).isDirectory()) throw new Error(`buildDist: out ${out} exists and is not a directory`);
  const names = readdirSync(out);
  if (names.length > 0 && !names.includes(DIST_MARKER)) {
    throw new Error(`buildDist: out ${out} is a non-empty directory not made by a build (no ${DIST_MARKER}); refusing to delete it`);
  }
}

/**
 * @param {{ root?: string; out: string; hash: string }} p
 * @returns {{ hash: string; files: string[]; precache: string[]; reachable: string[] }}
 */
export function buildDist(p) {
  const root = p.root ?? ROOT;
  const out = resolve(p.out);
  const { hash } = p;
  if (!RE_HASH.test(hash)) throw new Error(`buildDist: bad build hash ${JSON.stringify(hash)}`);
  checkOut(out, root);
  genRegistry(root);
  rmSync(out, { recursive: true, force: true });
  mkdirSync(out, { recursive: true });
  writeFileSync(join(out, DIST_MARKER), 'written by scripts/gen-sw.js; this directory is deleted and rebuilt on every build\n');
  const vdir = `v/${hash}`;

  /** @param {string} fromRel @param {string} toRel */
  const copy = (fromRel, toRel) => {
    const dst = join(out, toRel);
    mkdirSync(dirname(dst), { recursive: true });
    copyFileSync(join(root, fromRel), dst);
  };

  // Modules.
  for (const abs of walk(join(root, 'src'))) {
    const rel = posixRel(relative(root, abs));
    if (rel.endsWith('.js')) copy(rel, `${vdir}/${rel}`);
  }
  // Root pages.
  const pages = ['index.html', 'teacher.html'].filter((f) => existsSync(join(root, f)));
  /** @type {string[]} */
  const entries = [];
  for (const f of pages) {
    const html = readFileSync(join(root, f), 'utf8');
    const rewritten = html.replace(/\b(src|href)\s*=\s*(["'])src\//g, (_m, a, q) => `${a}=${q}${vdir}/src/`);
    for (const s of moduleScripts(html)) entries.push(posix.normalize(s));
    writeFileSync(join(out, f), rewritten);
  }
  if (!readFileSync(join(out, 'index.html'), 'utf8').includes(`src="${vdir}/src/app/boot.js"`)) {
    throw new Error('buildDist: index.html does not load src/app/boot.js');
  }
  copy('manifest.webmanifest', 'manifest.webmanifest');
  writeIcons(join(out, 'icons'));
  for (const f of ['sync.php', 'pair.php', 'lib.php']) copy(`api/${f}`, `api/${f}`);
  copy('api/.htaccess', '.htaccess');
  for (const f of ['index.html', 'style.css']) copy(`proto/${f}`, `proto/${f}`);
  for (const abs of walk(join(root, 'proto', 'js'))) {
    const rel = posixRel(relative(root, abs));
    if (rel.endsWith('.js')) copy(rel, rel);
  }

  // Precache: everything shipped except the API, .htaccess and sw.js itself.
  const shipped = walk(out).map((a) => posixRel(relative(out, a))).filter((f) => f !== DIST_MARKER);
  const precache = shipped.filter((f) => !f.startsWith('api/') && f !== '.htaccess' && f !== 'sw.js');
  const reachable = reachableModules(root, entries.length ? entries : ['src/app/boot.js']);
  const missing = reachable.filter((m) => !precache.includes(`${vdir}/${m}`));
  if (missing.length) throw new Error(`buildDist: reachable modules not precached: ${missing.join(', ')}`);
  for (const f of precache) if (!statSync(join(out, f)).isFile()) throw new Error(`buildDist: precache entry ${f} missing`);
  writeFileSync(join(out, 'sw.js'), swSource({ build: hash, precache }));

  const files = walk(out).map((a) => posixRel(relative(out, a))).filter((f) => f !== DIST_MARKER);
  const texts = files.filter((f) => /\.(html|css|js|webmanifest)$/.test(f)).map((f) => ({
    path: f, text: readFileSync(join(out, f), 'utf8'),
    strict: f === 'sw.js' || f === `${vdir}/src/app/boot.js` || f.startsWith(`${vdir}/src/store/`),
  }));
  const abs = absoluteUrlViolations(texts);
  if (abs.length) throw new Error(`buildDist: absolute URLs:\n  ${abs.join('\n  ')}`);
  return { hash, files, precache, reachable };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const get = (/** @type {string} */ k) => { const i = args.indexOf(k); return i >= 0 ? args[i + 1] : undefined; };
  const hash = get('--hash');
  if (!hash) { console.error('usage: node scripts/gen-sw.js --hash <hash> [--out dist] [--root .]'); process.exit(2); }
  const r = buildDist({ hash, out: get('--out') ?? join(ROOT, 'dist'), root: get('--root') ? resolve(/** @type {string} */ (get('--root'))) : ROOT });
  console.log(`gen-sw: build ${r.hash}: ${r.files.length} files, ${r.precache.length} precached, ${r.reachable.length} reachable modules`);
}
